section.sourcecode:
{
    "providerId": "example.com",
    "providerName": "Example Web Hosting",
    "serviceId": "cdn",
    "serviceName": "Example CDN",
    "version": 1,
    "vnd.example.contact": {
        "supportUrl": "https://support.example.com/cdn",
        "email": "support@example.com"
    },
    "vnd.example.lockRecords": true,
    "crit": ["vnd.example.lockRecords"],
    "records": [
        {
            "type": "A",
            "host": "www",
            "pointsTo": "%ip%",
            "ttl": 600,
            "vnd.example.proxied": true,
            "crit": ["vnd.example.proxied"]
        },
        {
            "type": "CNAME",
            "host": "static",
            "pointsTo": "cdn.example.com",
            "ttl": 600,
            "vnd.example.comment": "Static content"
        }
    ]
}
